"""Symbol listings (``references``, ``names``, ``search``).

Secret: which files a listing covers, which identifiers count as the same
symbol as the one under the cursor, which bindings each listing reports
(module level, every scope, or the searchable definitions), how a query
matches names, and how results are ordered.
"""

import os
import re

from . import navigation, scopes
from .inference import Project
from .modules import project_files
from .source import SourceFile

FILE = "file"
PROJECT = "project"


def references(path, line, col, scope=FILE, root=None):
    """Occurrences of the symbol at the cursor: dicts of module_path, line,
    column and is_definition."""
    source = SourceFile(path)
    source.check_position(line, col)
    project = Project(source.path, source.text(), root)
    found = navigation.find(project.main, line, col)
    if found is None:
        raise navigation.NotOnName("no name at %d:%d" % (line, col))
    name, _, _, occurrence = found
    wanted = navigation.identity(project, occurrence)
    describer = navigation.describer(project)
    paths = [source.path]
    if scope == PROJECT:
        paths += [p for p in project_files(project.root) if os.path.abspath(p) != source.path]
    pattern = re.compile(r"(?<!\w)%s(?!\w)" % re.escape(name))
    results = {}
    for file_path in paths:
        if file_path != source.path and not _mentions(file_path, pattern):
            continue
        analysis = project.analysis(file_path)
        for number, column, candidate in navigation.occurrences(analysis, name):
            keys = navigation.identity(project, candidate)
            if keys & wanted or (not wanted and not keys and file_path == source.path):
                key = (describer.relative(file_path), number, column)
                results[key] = results.get(key, False) or candidate.is_definition()
    covered = {os.path.abspath(p) for p in paths}
    for site_path, number, column in navigation.definition_sites(occurrence, project):
        if site_path and os.path.abspath(site_path) in covered:
            results[(describer.relative(site_path), number, column)] = True
    return [{"module_path": module_path, "line": number, "column": column,
             "is_definition": definition}
            for (module_path, number, column), definition in sorted(results.items())]


def names(path, all_scopes=False, root=None):
    """Definition records (plus ``is_definition``) of the names bound in a file."""
    source = SourceFile(path)
    project = Project(source.path, source.text(), root)
    tree = project.main.tree
    if all_scopes:
        bindings = list(_all_bindings(tree.module))
    else:
        bindings = [b for b in tree.module.events if b.home is tree.module]
    describer = navigation.describer(project)
    records = {}
    for binding in bindings:
        if binding.form == scopes.STAR or not binding.name:
            continue
        record = describer.binding(binding)
        if record is not None:
            record["is_definition"] = True
            records.setdefault((record["line"], record["column"], record["name"]), record)
    return [records[key] for key in sorted(records)]


def search(query, root=None):
    """Definition records (without docstrings) of the project's searchable names
    containing ``query``, best matches first."""
    root = os.path.abspath(root or os.getcwd())
    project = Project(None, None, root)
    describer = navigation.describer(project)
    wanted = query.lower()
    found = {}
    for file_path in project_files(root):
        tree = project.analysis(file_path).tree
        for binding in _searchable(tree.module):
            lowered = binding.name.lower()
            if wanted not in lowered:
                continue
            record = describer.binding(binding)
            if record is None:
                continue
            record.pop("docstring", None)
            rank = 0 if lowered == wanted else 1 if lowered.startswith(wanted) else 2
            key = (rank, record["module_path"], record["line"], record["column"], record["name"])
            found.setdefault(key, record)
    return [found[key] for key in sorted(found)]


def _mentions(path, pattern):
    try:
        with open(path, "rb") as handle:
            text = handle.read().decode("utf-8", errors="replace")
    except OSError:
        return False
    return pattern.search(text) is not None


def _all_bindings(scope):
    yield from scope.events
    yield from scope.instance_events
    for child in scope.children:
        yield from _all_bindings(child)


def _searchable(scope):
    """Functions and classes outside function bodies, and module-level assignments."""
    for binding in scope.events:
        if binding.home is not scope or not binding.name:
            continue
        if binding.form in (scopes.DEF, scopes.CLASS) or \
                (binding.form == scopes.ASSIGN and scope.kind == scopes.Scope.MODULE):
            yield binding
    for child in scope.children:
        if child.kind == scopes.Scope.CLASS:
            yield from _searchable(child)
"""Result serialization.

Secret: the wire format of the result (compact JSON with a ``completions``
array of name/complete/type/description objects, a ``definitions`` array of
definition objects, a ``signatures`` array, or a ``references`` array,
newline-terminated).
"""

import json
import sys


_DEFINITION_FIELDS = ("name", "type", "full_name", "module_path", "line", "column",
                      "description", "docstring")


def write_completions(completions, stream=None):
    """``completions``: iterable of (name, complete, type, description)."""
    payload = {"completions": [
        {"name": name, "complete": complete, "type": kind, "description": description}
        for name, complete, kind, description in completions
    ]}
    _write(payload, stream)


def write_definitions(definitions, stream=None):
    """``definitions``: iterable of dicts with the definition fields."""
    payload = {"definitions": [{field: d[field] for field in _DEFINITION_FIELDS}
                               for d in definitions]}
    _write(payload, stream)


def write_signatures(signatures, stream=None):
    """``signatures``: dicts with name, params, index, description, docstring."""
    fields = ("name", "params", "index", "description", "docstring")
    _write({"signatures": [{f: s[f] for f in fields} for s in signatures]}, stream)


def write_references(references, stream=None):
    """``references``: dicts with module_path, line, column, is_definition."""
    fields = ("module_path", "line", "column", "is_definition")
    _write({"references": [{f: r[f] for f in fields} for r in references]}, stream)


def write_search_results(definitions, stream=None):
    """``definitions``: definition dicts (their docstrings are left out)."""
    fields = [f for f in _DEFINITION_FIELDS if f != "docstring"]
    found = [{f: d[f] for f in fields} for d in definitions]
    _write({"definitions": found, "results": found}, stream)


def write_names(definitions, stream=None):
    """``definitions``: definition dicts with ``is_definition``."""
    fields = _DEFINITION_FIELDS + ("is_definition",)
    found = [{f: d[f] for f in fields} for d in definitions]
    _write({"definitions": found, "names": found}, stream)


def _write(payload, stream):
    text = json.dumps(payload, separators=(",", ":"), ensure_ascii=False) + "\n"
    stream = stream or sys.stdout
    if hasattr(stream, "buffer"):
        stream.flush()
        stream.buffer.write(text.encode("utf-8"))
        stream.buffer.flush()
    else:
        stream.write(text)
        stream.flush()
"""Source file access.

Secret: how a file on disk is read, decoded and split into lines, and how a
(1-based line, 0-based column) cursor is validated against it.
"""

import os


class SourceError(Exception):
    """The file cannot be used as input (missing, undecodable, bad cursor)."""


class SourceFile:
    def __init__(self, path):
        if not os.path.isfile(path):
            raise SourceError("not a regular file: %s" % path)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except OSError as exc:
            raise SourceError("cannot read %s: %s" % (path, exc))
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise SourceError("file is not valid UTF-8: %s" % path)
        if text.startswith("\ufeff"):
            text = text[1:]
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        self._path = os.path.abspath(path)
        self._lines = text.split("\n")

    @property
    def path(self):
        return self._path

    def text(self):
        return "\n".join(self._lines)

    def lines(self):
        """The file's lines without line terminators (a copy)."""
        return list(self._lines)

    def check_position(self, line, col):
        if line < 1 or line > len(self._lines):
            raise SourceError("line %d out of range" % line)
        if col < 0 or col > len(self._lines[line - 1]):
            raise SourceError("column %d out of range" % col)

    def text_before(self, line, col):
        """All text from the start of the file up to the cursor."""
        head = self._lines[: line - 1]
        head.append(self._lines[line - 1][:col])
        return "\n".join(head)
"""Error-tolerant parsing.

Secret: the repair strategy used to turn syntactically broken source into a
syntax tree. Lines keep their numbers, so positions in the returned tree
match positions in the original text.
"""

import ast
import keyword
import re

_ORIGINAL, _PASSED, _BLANKED = 0, 1, 2
_HEADER_RE = re.compile(r"on line (\d+)")
_DEF_RE = re.compile(r"^(\s*)(async\s+)?def\s+([^\W\d]\w*)")
_CLASS_RE = re.compile(r"^(\s*)class\s+([^\W\d]\w*)")
_PARAM_RE = re.compile(r"\s*\*{0,2}\s*([^\W\d]\w*)")
_SALVAGED = 3


def parse_tolerant(text):
    """Return an ``ast.Module`` for ``text``, repairing errors as needed."""
    lines = text.replace("\0", " ").split("\n")
    state = [_ORIGINAL] * len(lines)
    patched_headers = set()
    for _ in range(4 * len(lines) + 20):
        try:
            return ast.parse("\n".join(lines))
        except SyntaxError as exc:
            if not _repair(lines, state, patched_headers, exc):
                break
        except (ValueError, RecursionError, MemoryError):
            break
    return ast.Module(body=[], type_ignores=[])


def _repair(lines, state, patched_headers, exc):
    msg = exc.msg or ""
    if msg.startswith("expected an indented block"):
        match = _HEADER_RE.search(msg)
        if match:
            header = int(match.group(1)) - 1
            if 0 <= header < len(lines) and header not in patched_headers:
                patched_headers.add(header)
                lines[header] = _with_pass_body(lines[header])
                return True
    idx = (exc.lineno or len(lines)) - 1
    idx = max(0, min(idx, len(lines) - 1))
    if msg.startswith("unterminated triple-quoted string") and ("eof", idx) not in patched_headers:
        patched_headers.add(("eof", idx))
        text = lines[idx][max(0, (exc.offset or 1) - 1):]
        quotes = [q for q in ('"""', "'''") if q in text]
        if quotes:
            lines[-1] += min(quotes, key=text.index)
            return True
    while idx >= 0 and (state[idx] == _BLANKED or not lines[idx].strip()):
        idx -= 1
    if idx < 0:
        return False
    if msg.startswith("expected 'except' or 'finally' block"):
        header = _find_try_header(lines, idx)
        if header is not None:
            lines[header] = lines[header][: _indent_width(lines[header])] + "if True:"
            return True
    if msg.startswith("unexpected indent"):
        _blank_block(lines, state, idx)
        return True
    if state[idx] == _ORIGINAL and lines[idx].rstrip().endswith(":"):
        salvaged = _salvage_header(lines[idx])
        if salvaged is not None and salvaged != lines[idx]:
            state[idx] = _SALVAGED
            lines[idx] = salvaged
            return True
    if state[idx] in (_ORIGINAL, _SALVAGED):
        stripped = lines[idx].lstrip()
        indent = lines[idx][: len(lines[idx]) - len(stripped)]
        state[idx] = _PASSED
        lines[idx] = indent + "pass"
    else:
        state[idx] = _BLANKED
        lines[idx] = ""
    return True


def _blank_block(lines, state, idx):
    """Blank an orphaned indented block: line ``idx`` and deeper/equal lines after it."""
    width = _indent_width(lines[idx])
    end = idx
    while end < len(lines) and (not lines[end].strip() or _indent_width(lines[end]) >= width):
        if lines[end].strip():
            state[end] = _BLANKED
            lines[end] = ""
        end += 1


def _find_try_header(lines, idx):
    """The ``try:`` line whose handlers are missing at line ``idx``."""
    limit = _indent_width(lines[idx]) if lines[idx].strip() else None
    for number in range(min(idx, len(lines) - 1), -1, -1):
        stripped = lines[number].strip()
        if not stripped:
            continue
        width = _indent_width(lines[number])
        if stripped.replace(" ", "") == "try:" and (limit is None or width <= limit):
            return number
        if limit is not None and width < limit:
            return None
    return None


def _indent_width(line):
    return len(line) - len(line.lstrip())


def _salvage_header(line):
    """Reduce a broken ``def``/``class`` header to a minimal valid one."""
    match = _DEF_RE.match(line)
    if match:
        params = []
        rest = line[match.end():]
        if rest.lstrip().startswith("("):
            inside = rest[rest.index("(") + 1: rest.rfind(":")]
            for piece in inside.split(","):
                found = _PARAM_RE.match(piece)
                if found and found.group(1) not in params \
                        and not keyword.iskeyword(found.group(1)):
                    params.append(found.group(1))
        return "%s%sdef %s(%s):" % (match.group(1), match.group(2) or "", match.group(3),
                                    ", ".join(params))
    match = _CLASS_RE.match(line)
    if match:
        return "%sclass %s:" % (match.group(1), match.group(2))
    return None


def _with_pass_body(line):
    """Give a block header such as ``if x:`` an inline ``pass`` body."""
    stripped = line.rstrip()
    if stripped.endswith(":"):
        return stripped + " pass"
    colon = stripped.rfind(":")
    if colon >= 0:
        return stripped[: colon + 1] + " pass"
    return stripped

